#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"

/* 
 * Optimization note:
 * Keep the stencil coefficient as a double to match the original literal
 * type (0.33333), so we preserve the original floating‐point semantics
 * even when DATA_TYPE is float.
 */
static const double JACOBI_COEF = 0.33333;


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i + 2) / n;
      B[i] = ((DATA_TYPE) i + 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local restrict-qualified pointers for A and B to give the
     compiler stronger aliasing guarantees, improving vectorization.
   - Hoist loop-invariant bounds and the stencil coefficient out of 
     the inner loops.
   - Use local scalar temporaries for neighbor accesses to improve
     register reuse and generate cleaner vectorizable code.
   - Preserve the original mathematical expression structure to keep
     floating-point semantics unchanged (same coefficient type and
     parenthesization).
*/
static
void kernel_jacobi_1d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* tsteps and n are intentionally unused inside the kernel body:
   * PolyBench uses the _PB_TSTEPS and _PB_N macros for the actual
   * loop bounds (possibly modified for validation/detection
   * configurations). Explicitly mark them unused to silence warnings
   * without changing behavior.
   */
  (void)tsteps;
  (void)n;

#pragma scop
  /* Local restrict-qualified pointers improve alias analysis.
   * The PolyBench allocation scheme guarantees A and B do not alias.
   */
  DATA_TYPE * restrict A_ptr = A;
  DATA_TYPE * restrict B_ptr = B;

  /* Inner-loop upper bound (exclusive). For _PB_N <= 1, this becomes
   * <= 0 and the loops naturally execute zero iterations, matching
   * the original behavior.
   */
  const int inner_end = _PB_N - 1;

  /* Stencil coefficient, kept as double to match literal 0.33333. */
  const double c = JACOBI_COEF;

  for (int t = 0; t < _PB_TSTEPS; t++)
    {
      /* First sweep: read from A, write into B.
       * Memory access pattern: contiguous, unit-stride loads/stores.
       * The compiler can trivially vectorize this loop.
       */
      for (int i = 1; i < inner_end; i++)
	{
	  const DATA_TYPE a_im1 = A_ptr[i-1];
	  const DATA_TYPE a_i   = A_ptr[i];
	  const DATA_TYPE a_ip1 = A_ptr[i+1];

	  /* Preserve original expression structure:
	   * 0.33333 * (A[i-1] + A[i] + A[i+1])
	   * Now: c * (a_im1 + a_i + a_ip1) with c as double,
	   * giving the same arithmetic conversions.
	   */
	  B_ptr[i] = (DATA_TYPE)(c * ( (double)a_im1 +
	                               (double)a_i   +
	                               (double)a_ip1 ));
	}

      /* Second sweep: read from B, write back into A.
       * Same access pattern as above, now operating on B.
       */
      for (int i = 1; i < inner_end; i++)
	{
	  const DATA_TYPE b_im1 = B_ptr[i-1];
	  const DATA_TYPE b_i   = B_ptr[i];
	  const DATA_TYPE b_ip1 = B_ptr[i+1];

	  A_ptr[i] = (DATA_TYPE)(c * ( (double)b_im1 +
	                               (double)b_i   +
	                               (double)b_ip1 ));
	}
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
