#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"

/* ------------------------------------------------------------------------
 * Tunable kernel parameters
 * ------------------------------------------------------------------------ */

/* Compile-time tunable unrolling factor for the Jacobi kernel.
 *  - Must be >= 1.
 *  - Reasonable values: 4, 8 or 16.
 *  - Can be overridden at compile time, e.g.:
 *        -DJACOBI_1D_UNROLL_FACTOR=16
 */
#ifndef JACOBI_1D_UNROLL_FACTOR
# define JACOBI_1D_UNROLL_FACTOR 8
#endif

/* Ensure the unroll factor is valid at compile time. */
_Static_assert(JACOBI_1D_UNROLL_FACTOR >= 1,
               "JACOBI_1D_UNROLL_FACTOR must be >= 1");


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
      {
	A[i] = ((DATA_TYPE) i+ 2) / n;
	B[i] = ((DATA_TYPE) i+ 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimization notes:
 *  - Use local restrict-qualified pointers to A and B to help the
 *    compiler vectorize and keep data in registers.
 *  - Hoist invariant quantities (problem sizes, stencil coefficient).
 *  - Apply a small 1D blocking/unrolling strategy: process
 *    JACOBI_1D_UNROLL_FACTOR consecutive points at a time using a
 *    short “sliding window” over the input array. This reduces the
 *    number of loads per output point by reusing neighbor values
 *    from the window while keeping the loop free of inter-iteration
 *    dependencies so it remains vectorizable.
 */
static
void __attribute__((flatten, noinline))
kernel_jacobi_1d(int tsteps,
                 int n,
                 DATA_TYPE POLYBENCH_1D(A,N,n),
                 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Alias the PolyBench array parameters with restrict pointers to
   * explicitly state that A and B do not alias, enabling better
   * optimization and vectorization. */
  DATA_TYPE * __restrict a = A;
  DATA_TYPE * __restrict b = B;

  /* Effective problem sizes as seen by PolyBench (may differ from
   * raw tsteps/n if PolyBench is configured to resize problems). */
  const int T = _PB_TSTEPS;
  const int N = _PB_N;

  /* No interior points or no time steps: nothing to do. */
  if (N <= 2 || T <= 0)
    return;

  /* Interior upper bound: we update indices i = 1 .. (limit - 1)
   * which corresponds to original i = 1 .. N-2. */
  const int limit = N - 1;

  /* Stencil coefficient (shared by all iterations). */
  const DATA_TYPE c = (DATA_TYPE)0.33333;

  /* Compile-time unroll factor (from the macro above). */
  enum { UF = JACOBI_1D_UNROLL_FACTOR };

  /* Small sliding window buffer used inside the unrolled loops.
   * We load UF+2 consecutive input elements (i-1 .. i+UF) and
   * compute UF outputs from them:
   *   out[i + k] = c * (win[k] + win[k+1] + win[k+2])
   */
  DATA_TYPE window[UF + 2];

#pragma scop
  for (int t = 0; t < T; ++t)
    {
      int i;

      /* ------------------------------------------------------------------
       * Sweep 1: update B from A
       *    B[i] = c * (A[i-1] + A[i] + A[i+1]), for i in [1, N-2]
       * ------------------------------------------------------------------ */

      i = 1;

      /* Unrolled / blocked region.
       * Condition i + UF <= limit ensures that:
       *   - All outputs B[i .. i+UF-1] are interior points (<= N-2).
       *   - The highest input index we use, A[i+UF], is <= A[N-1].
       */
      for (; i + UF <= limit; i += UF)
	{
	  /* Load the input window from A. */
#pragma GCC unroll
	  for (int k = 0; k < UF + 2; ++k)
	    window[k] = a[i - 1 + k];

	  /* Compute UF Jacobi updates using the window. */
#pragma GCC unroll
	  for (int k = 0; k < UF; ++k)
	    b[i + k] = c * (window[k] + window[k + 1] + window[k + 2]);
	}

      /* Remainder loop for any trailing interior points that do not
       * fit into a full UF-sized block (also handles small N where
       * N-2 < UF, in which case only this loop runs). */
      for (; i < limit; ++i)
	b[i] = c * (a[i - 1] + a[i] + a[i + 1]);


      /* ------------------------------------------------------------------
       * Sweep 2: update A from B
       *    A[i] = c * (B[i-1] + B[i] + B[i+1]), for i in [1, N-2]
       * ------------------------------------------------------------------ */

      i = 1;

      for (; i + UF <= limit; i += UF)
	{
#pragma GCC unroll
	  for (int k = 0; k < UF + 2; ++k)
	    window[k] = b[i - 1 + k];

#pragma GCC unroll
	  for (int k = 0; k < UF; ++k)
	    a[i + k] = c * (window[k] + window[k + 1] + window[k + 2]);
	}

      for (; i < limit; ++i)
	a[i] = c * (b[i - 1] + b[i] + b[i + 1]);
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
