    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   -------------------
   The original kernel performed, for each time step t:

     1) B[i] = (A[i-1] + A[i] + A[i+1]) / 3    for i = 1..N-2
     2) A[i] = (B[i-1] + B[i] + B[i+1]) / 3    for i = 1..N-2

   as two separate spatial sweeps.

   This optimized kernel *fuses* those two spatial sweeps into a
   single pass over the domain for each time step. The key idea is
   to pipeline the computation along i:

     - We compute B[i] from A[..] as before.
     - Once B[i] is known, and we also have B[i-1] and B[i-2]
       from previous iterations of the same time step, we can
       immediately compute A[i-1] using:
         A[i-1] = (B[i-2] + B[i-1] + B[i]) / 3.

   This preserves the original Jacobi semantics because:
     * Every B[i] for the current time step is computed **only**
       from A values of the current time step (A^t).
     * Every A[i] for the next time step is computed **only** from
       B values of the current time step (B^{t+1}).
     * Boundary elements A[0], A[N-1], B[0], B[N-1] remain unchanged.

   Memory behavior improvement:
     - Original: two full sweeps; the second sweep loads B[i-1..i+1]
       from memory again.
     - Optimized: we keep the neighboring B values needed for the A
       update in a small sliding window of scalars, avoiding almost
       all loads from B during the second phase. This significantly
       reduces memory traffic, while still streaming through A and B
       contiguously in memory.

   The loops remain sequential in the time dimension (t), preserving
   all data dependencies across time steps.
*/
static
void kernel_jacobi_1d [[gnu::flatten, gnu::noinline]] (int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* tsteps and n are deliberately unused directly: _PB_TSTEPS and
     _PB_N (from PolyBench) are the canonical loop bounds. */
  (void)tsteps;
  (void)n;

  /* Use restrict-qualified pointers locally to help the compiler with
     alias analysis and enable better optimization and vectorization
     within the kernel. */
  DATA_TYPE * __restrict__ A_ = A;
  DATA_TYPE * __restrict__ B_ = B;

  const int T  = _PB_TSTEPS;
  const int N_ = _PB_N;

  /* Constant stencil coefficient. Kept identical to the original code
     to preserve floating-point behavior as much as possible. */
  const DATA_TYPE c = (DATA_TYPE)0.33333;

#pragma scop
  for (int t = 0; t < T; t++)
    {
      /* No interior points when N_ <= 2, so nothing to do.
         This matches the original loop condition: i from 1 to N_-2. */
      if (N_ > 2)
      {
        /* Left boundary B_[0] is constant across all time steps. */
        DATA_TYPE b_im2 = B_[0];
        DATA_TYPE b_im1;

        /* Seed the pipeline with i = 1.

           We compute:
             B[1] = c * (A[0] + A[1] + A[2]);

           but delay any A updates until we have enough neighboring
           B values (i.e., until i >= 2). */
        {
          const DATA_TYPE a0 = A_[0];
          const DATA_TYPE a1 = A_[1];
          const DATA_TYPE a2 = A_[2];

          const DATA_TYPE b1 = c * (a0 + a1 + a2);
          B_[1] = b1;
          b_im1 = b1;
        }

        /* Main pipelined loop for i = 2 .. N_-2.

           For each i:
             1) Compute B[i] from A[i-1], A[i], A[i+1].
             2) Compute A[i-1] using B[i-2], B[i-1], B[i].

           The three B values needed for A[i-1] are kept in the
           scalar variables:
             - b_im2: B[i-2] from two iterations ago,
             - b_im1: B[i-1] from the previous iteration,
             - b_i  : B[i]   from the current iteration.

           This is semantically equivalent to the original code,
           but avoids reloading B[i-2..i] from memory. */
        for (int i = 2; i < N_ - 1; ++i)
        {
          const DATA_TYPE a_im1 = A_[i - 1];
          const DATA_TYPE a_i   = A_[i];
          const DATA_TYPE a_ip1 = A_[i + 1];

          const DATA_TYPE b_i = c * (a_im1 + a_i + a_ip1);
          B_[i] = b_i;

          /* A[i-1] update: uses B[i-2], B[i-1], B[i]. */
          A_[i - 1] = c * (b_im2 + b_im1 + b_i);

          /* Slide the B-window for the next iteration. */
          b_im2 = b_im1;
          b_im1 = b_i;
        }

        /* After the loop:
             b_im2 == B[N_-3]
             b_im1 == B[N_-2]
           and B[N_-1] is the (fixed) right boundary.

           We still need to update the last interior point:
             A[N_-2] = c * (B[N_-3] + B[N_-2] + B[N_-1]); */
        A_[N_ - 2] = c * (b_im2 + b_im1 + B_[N_ - 1]);
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
