 *   - Controls the blocking size for the spatial (i) dimension.
 *   - The kernel processes the 1D domain in chunks of this many elements.
 *   - This can be overridden at compile time, e.g.:
 *       -DJACOBI_1D_BLOCK_SIZE=4096
 *
 *   For a purely 1D streaming stencil the impact is modest, but on
 *   large problem sizes it can help instruction cache locality and
 *   interact better with prefetchers.
 * --------------------------------------------------------------------- */
#ifndef JACOBI_1D_BLOCK_SIZE
# define JACOBI_1D_BLOCK_SIZE 1024
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i + 2) / n;
      B[i] = ((DATA_TYPE) i + 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *   - Use local pointer aliases for A and B to avoid repeated
 *     address arithmetic on VLAs and to make the access pattern
 *     explicit for the compiler.
 *   - Block the spatial loop with JACOBI_1D_BLOCK_SIZE. Within one
 *     time step, all updates of B[i] (or A[i]) are independent, so
 *     changing the order over i does not change the numerical
 *     result; we still complete the whole A->B sweep before any
 *     B->A sweep in the same time step.
 *   - Add a vectorization hint (#pragma GCC ivdep) on the innermost
 *     loops, emphasizing that there are no loop-carried dependencies
 *     across iterations in i for a fixed t. This helps compilers
 *     generate SIMD code more aggressively under strict FP semantics.
 */
static
void kernel_jacobi_1d [[gnu::flatten, gnu::noinline]] (int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t;

  /* Local pointer aliases help the compiler optimize address
   * calculations, especially when POLYBENCH_1D expands to a VLA.
   * We never use A or B directly below, only these aliases. */
  DATA_TYPE *a = A;
  DATA_TYPE *b = B;

  /* Hoist the constant used in the stencil; the compiler will
   * usually do this anyway, but making it explicit clarifies
   * intent and can aid constant propagation. */
  const DATA_TYPE c = (DATA_TYPE)0.33333;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      /* ---------------------------------------------------------
       * First Jacobi sweep: read from a (A), write to b (B)
       * B[i] = c * (A[i-1] + A[i] + A[i+1])
       * 
       * We process i in blocks of JACOBI_1D_BLOCK_SIZE to improve
       * cache behavior on large N. Within a single time step,
       * all B[i] updates are independent, so this reordering
       * over i is semantics-preserving.
       * ------------------------------------------------------- */
      int ii;
      for (ii = 1; ii < _PB_N - 1; ii += JACOBI_1D_BLOCK_SIZE)
	{
	  /* Compute upper bound of this block; clamp at _PB_N - 1
	   * because the original loop used i < _PB_N - 1. */
	  int i_end = ii + JACOBI_1D_BLOCK_SIZE;
	  if (i_end > _PB_N - 1)
	    i_end = _PB_N - 1;

	  int i;

	  /* Vectorization hint: for a fixed t and fixed block,
	   * iterations in i have no cross-iteration dependencies
	   * (each B[i] depends only on A[*], which is not modified
	   * in this loop). */
#pragma GCC ivdep
	  for (i = ii; i < i_end; i++)
	    {
	      b[i] = c * (a[i-1] + a[i] + a[i+1]);
	    }
	}

      /* ---------------------------------------------------------
       * Second Jacobi sweep: read from b (B), write back to a (A)
       * A[i] = c * (B[i-1] + B[i] + B[i+1])
       *
       * Again we block over i for the same reasons. All A[i]
       * updates in this loop are independent because B is only
       * read, not written.
       * ------------------------------------------------------- */
      for (ii = 1; ii < _PB_N - 1; ii += JACOBI_1D_BLOCK_SIZE)
	{
	  int i_end = ii + JACOBI_1D_BLOCK_SIZE;
	  if (i_end > _PB_N - 1)
	    i_end = _PB_N - 1;

	  int i;

#pragma GCC ivdep
	  for (i = ii; i < i_end; i++)
	    {
	      a[i] = c * (b[i-1] + b[i] + b[i+1]);
	    }
	}
    }
#pragma endscop

}


